H,W=16,26
out=[[0]*W for _ in range(H)]
# Rotate 3x3 key and scale 4; align to coarse 8 pattern origin row3,col2
rot=[[3,0,0],[0,4,4],[2,2,0]]
for br in range(3):
 for bc in range(3):
  v=rot[br][bc]
  if v:
   for r in range(3+4*br, 3+4*(br+1)):
    for c in range(2+4*bc, 2+4*(bc+1)):
     out[r][c]=v
# non-8 key markers remain as in input
for r,c,v in [(6,22,4),(7,22,4),(7,23,2),(8,21,3),(8,23,2)]: out[r][c]=v
print('\n'.join(' '.join(map(str,row)) for row in out))
